// Read-only preparation shared by a Pending row and its eventual opener.
// Failed/incomplete reads are never retained as a finished result.
export function createRevealPreparation({ limit = 32, complete = value => value != null } = {}) {
  const entries = new Map();
  const trim = () => {
    // Never evict a read that an opener can still join. Only completed,
    // rebuildable payloads count against the retained-result budget.
    let retained = [...entries.values()].filter(entry => entry.complete).length;
    for (const [key, entry] of entries) {
      if (retained <= limit) break;
      if (entry.complete) { entries.delete(key); retained--; }
    }
  };
  return {
    get(key, load) {
      if (entries.has(key)) {
        const entry = entries.get(key);
        entries.delete(key);
        entries.set(key, entry);
        return entry.promise;
      }
      const entry = { promise: null, value: null, complete: false };
      const pending = Promise.resolve().then(load).then(value => {
        if (complete(value)) { entry.value = value; entry.complete = true; trim(); }
        else if (entries.get(key) === entry) entries.delete(key);
        return value;
      }, error => {
        if (entries.get(key) === entry) entries.delete(key);
        throw error;
      });
      entry.promise = pending;
      entries.set(key, entry);
      return pending;
    },
    peek(key) { return entries.get(key)?.value ?? null; },
    clear() { entries.clear(); },
  };
}
